const LOCAL_LOGO_PATH = "data:image/png;base64,";

// كائن مرجعي عام لمكتبة Chart.js
let myChart = null;

// تهيئة التطبيق عند اكتمال تحميل الصفحة بالكامل
document.addEventListener("DOMContentLoaded", () => {
    // تعيين مصدر الشعار
    const logoImg = document.getElementById("reportLogoImg");
    if (logoImg && typeof LOCAL_LOGO_PATH !== 'undefined') {
        logoImg.src = "logo.png";
    }

    // بناء استمارة المجالات والتبويبات
    if (typeof renderDomainsForm === 'function') {
        renderDomainsForm();
    }

    // تحديث قائمة السجلات المسجلة
    updateSavedChildrenDropdown();

    // ضبط تاريخ التقييم التلقائي على تاريخ اليوم
    const evalDateElem = document.getElementById('evalDate');
    if (evalDateElem) {
        evalDateElem.valueAsDate = new Date();
    }

    // ربط مستمع تغيير اسم الطفل لتحديث الشريط العلوي اللاصق
    const childNameInput = document.getElementById('childName');
    if (childNameInput) {
        childNameInput.addEventListener('input', () => {
            const stickyName = document.getElementById('stickyChildName');
            if (stickyName) {
                stickyName.innerText = childNameInput.value.trim() || 'طفل غير مسجل';
            }
        });
    }

    // مراقبة التمرير لإظهار الشريط العائم عند النزول
    window.addEventListener('scroll', handleStickyBarScroll);

    // تحديث الإحصائيات الحية
    updateLiveStats();
});

/**
 * إظهار/إخفاء شريط الإجراءات العائم السريع عند التمرير
 */
function handleStickyBarScroll() {
    const stickyBar = document.getElementById('stickyAssessmentBar');
    if (!stickyBar) return;

    if (window.scrollY > 280) {
        stickyBar.classList.add('visible');
    } else {
        stickyBar.classList.remove('visible');
    }
}

/**
 * تحديث شريط المؤشرات الحية، الإحصاءات الفورية، نسب الإنجاز، وشارات التبويبات
 */
function updateLiveStats() {
    let hyperCount = 0;
    let hyperScoreSum = 0;
    let hypoCount = 0;
    let hypoScoreSum = 0;
    let affectedDomainsSet = new Set();
    let totalItemsEvaluated = 0;
    let totalItemsAvailable = 0;

    if (typeof domainsData === 'undefined') return;

    domainsData.forEach(domain => {
        let domainAffectedCount = 0;

        domain.items.forEach((_, index) => {
            totalItemsAvailable++;
            const num = index + 1;
            const scoreElem = document.getElementById(`${domain.id}_${num}_score`);
            const typeElem = document.getElementById(`${domain.id}_${num}_type`);

            const score = scoreElem ? parseInt(scoreElem.value) || 0 : 0;
            const type = typeElem ? typeElem.value : 'hyper';

            // إذا كان التقييم قد تم اختياره صراحة
            if (scoreElem) {
                totalItemsEvaluated++;
            }

            if (score > 0) {
                affectedDomainsSet.add(domain.id);
                domainAffectedCount++;
                if (type === 'hyper') {
                    hyperCount++;
                    hyperScoreSum += score;
                } else {
                    hypoCount++;
                    hypoScoreSum += score;
                }
            }
        });

        // البند اليدوي
        const mScoreElem = document.getElementById(`${domain.id}_manual_score`);
        const mTypeElem = document.getElementById(`${domain.id}_manual_type`);
        const mTextElem = document.getElementById(`${domain.id}_manual_text`);

        const mText = mTextElem ? mTextElem.value.trim() : '';
        const mScore = mScoreElem ? parseInt(mScoreElem.value) || 0 : 0;
        const mType = mTypeElem ? mTypeElem.value : 'hyper';

        if (mText && mScore > 0) {
            affectedDomainsSet.add(domain.id);
            domainAffectedCount++;
            if (mType === 'hyper') {
                hyperCount++;
                hyperScoreSum += mScore;
            } else {
                hypoCount++;
                hypoScoreSum += mScore;
            }
        }

        // تحديث شارة التبويب لهذا المجال
        const tabBadge = document.getElementById(`tab_badge_${domain.id}`);
        if (tabBadge) {
            tabBadge.innerText = domainAffectedCount;
            if (domainAffectedCount > 0) {
                tabBadge.classList.add('has-badge-difficulty');
            } else {
                tabBadge.classList.remove('has-badge-difficulty');
            }
        }
    });

    // تحديث شارة تبويب الكل
    const tabBadgeAll = document.getElementById('tab_badge_all');
    if (tabBadgeAll) {
        tabBadgeAll.innerText = hyperCount + hypoCount;
    }

    // تحديث بطاقات الإحصائيات
    const liveHyperElem = document.getElementById('liveHyperCount');
    const liveHypoElem = document.getElementById('liveHypoCount');
    const liveDomainsElem = document.getElementById('liveDomainsCount');

    if (liveHyperElem) liveHyperElem.innerText = `${hyperCount} بند (${hyperScoreSum} درجة)`;
    if (liveHypoElem) liveHypoElem.innerText = `${hypoCount} بند (${hypoScoreSum} درجة)`;
    if (liveDomainsElem) liveDomainsElem.innerText = `${affectedDomainsSet.size} من 9`;

    // حساب نسبة البنود المتأثرة وشريط التقدم
    const totalDifficulties = hyperCount + hypoCount;
    const progressFill = document.getElementById('assessmentProgressFill');
    const progressPercentText = document.getElementById('assessmentProgressPercent');
    const stickyProgressText = document.getElementById('stickyProgressPercent');

    // نحسب تقدم الإنجاز بناء على المجالات المتأثرة والبنود
    const progressPercent = Math.min(100, Math.round((affectedDomainsSet.size / 9) * 100));

    if (progressFill) progressFill.style.width = `${progressPercent}%`;
    if (progressPercentText) progressPercentText.innerText = `${progressPercent}%`;
    if (stickyProgressText) stickyProgressText.innerText = `${progressPercent}%`;

    const stickyCounts = document.getElementById('stickyDifficultyCount');
    if (stickyCounts) {
        stickyCounts.innerText = `${totalDifficulties} صعوبة مسجلة (${affectedDomainsSet.size} أنظمة)`;
    }
}

/**
 * دالة تفريغ النموذج وبدء تقييم جديد
 */
function resetEvaluationForm() {
    if (!confirm('هل أنت متأكد من رغبتك في تفريغ حقول التقييم وبدء جلسة جديدة للطفل؟')) {
        return;
    }

    const form = document.getElementById('sensoryForm');
    if (form) form.reset();

    const evalDateElem = document.getElementById('evalDate');
    if (evalDateElem) evalDateElem.valueAsDate = new Date();

    // إعادة رسم الاستمارة لتصفير القيم
    if (typeof renderDomainsForm === 'function') {
        renderDomainsForm();
    }

    // إخفاء صندوق التقرير
    const reportBox = document.getElementById('reportBox');
    if (reportBox) reportBox.style.display = 'none';

    // العودة للتبويب الأول
    if (typeof switchDomainTab === 'function') {
        switchDomainTab('v');
    }

    updateLiveStats();
}

/**
 * دالة استخراج التقرير الشامل والتحليل البياني وبناء الخطة العلاجية
 */
async function generateFullReport() {
    const form = document.getElementById('sensoryForm');
    if (!form) return;

    if (!form.checkValidity()) {
        form.reportValidity();
        return;
    }

    const btnMain = document.getElementById('btnMainGenerate');
    const stickyBtn = document.getElementById('stickyBtnGenerate');
    setButtonLoading(btnMain, 'جاري تحليل الدرجات وبناء الخطة...');
    if (stickyBtn) setButtonLoading(stickyBtn, 'جاري التوليد...');

    // نقل البيانات الأساسية للتقرير المطبوع
    const rName = document.getElementById('rName');
    const rAge = document.getElementById('rAge');
    const rGender = document.getElementById('rGender');
    const rDate = document.getElementById('rDate');
    const rEvaluator = document.getElementById('rEvaluator');

    if (rName) rName.innerText = document.getElementById('childName')?.value || 'غير محدد';
    if (rAge) rAge.innerText = document.getElementById('childAge')?.value || 'غير محدد';
    if (rGender) rGender.innerText = document.getElementById('childGender')?.value || 'غير محدد';
    if (rDate) rDate.innerText = document.getElementById('evalDate')?.value || 'غير محدد';
    if (rEvaluator) rEvaluator.innerText = document.getElementById('evaluator')?.value || 'غير محدد';

    const hyperList = document.getElementById('hyperList');
    const hypoList = document.getElementById('hypoList');
    if (hyperList) hyperList.innerHTML = '';
    if (hypoList) hypoList.innerHTML = '';

    // درجات الأنظمة التسعة
    let hyperScores = { v: 0, t: 0, a: 0, vsl: 0, olf: 0, gus: 0, mus: 0, p: 0, c: 0 };
    let hypoScores = { v: 0, t: 0, a: 0, vsl: 0, olf: 0, gus: 0, mus: 0, p: 0, c: 0 };

    let affectedDomains = [];
    let hyperCount = 0;
    let hypoCount = 0;

    let evaluationDetails = {
        hyperItems: [],
        hypoItems: []
    };

    domainsData.forEach(domain => {
        domain.items.forEach((itemText, index) => {
            const num = index + 1;
            const scoreElem = document.getElementById(`${domain.id}_${num}_score`);
            const typeElem = document.getElementById(`${domain.id}_${num}_type`);

            const score = scoreElem ? parseInt(scoreElem.value) || 0 : 0;
            const type = typeElem ? typeElem.value : 'hyper';

            if (score > 0) {
                if (!affectedDomains.includes(domain.id)) affectedDomains.push(domain.id);

                const itemData = { 
                    name: itemText, 
                    score: score, 
                    domainId: domain.id, 
                    domainName: domain.name 
                };

                const scoreLabel = score === 3 ? 'شديد (3/3)' : (score === 2 ? 'متوسط (2/3)' : 'بسيط (1/3)');

                if (type === 'hyper') {
                    hyperScores[domain.id] = (hyperScores[domain.id] || 0) + score;
                    hyperCount++;
                    addToList(hyperList, `<b>${itemText}</b> - <span style="color:#dc2626; font-weight:bold;">[الشدة: ${scoreLabel}]</span> <small style="color:#64748b;">(${domain.name})</small>`);
                    evaluationDetails.hyperItems.push(itemData);
                } else {
                    hypoScores[domain.id] = (hypoScores[domain.id] || 0) + score;
                    hypoCount++;
                    addToList(hypoList, `<b>${itemText}</b> - <span style="color:#2563eb; font-weight:bold;">[الشدة: ${scoreLabel}]</span> <small style="color:#64748b;">(${domain.name})</small>`);
                    evaluationDetails.hypoItems.push(itemData);
                }
            }
        });

        // البند اليدوي
        const mTextElem = document.getElementById(`${domain.id}_manual_text`);
        const mScoreElem = document.getElementById(`${domain.id}_manual_score`);
        const mTypeElem = document.getElementById(`${domain.id}_manual_type`);

        const mText = mTextElem ? mTextElem.value.trim() : '';
        const mScore = mScoreElem ? parseInt(mScoreElem.value) || 0 : 0;
        const mType = mTypeElem ? mTypeElem.value : 'hyper';

        if (mText && mScore > 0) {
            if (!affectedDomains.includes(domain.id)) affectedDomains.push(domain.id);

            const manualData = { 
                name: `[بند يدوي] ${mText}`, 
                score: mScore, 
                domainId: domain.id, 
                domainName: domain.name 
            };

            const scoreLabel = mScore === 3 ? 'شديد (3/3)' : (mScore === 2 ? 'متوسط (2/3)' : 'بسيط (1/3)');

            if (mType === 'hyper') {
                hyperScores[domain.id] = (hyperScores[domain.id] || 0) + mScore;
                hyperCount++;
                addToList(hyperList, `<b>[بند مخصص للأخصائي] ${mText}</b> - <span style="color:#dc2626; font-weight:bold;">[الشدة: ${scoreLabel}]</span> <small style="color:#64748b;">(${domain.name})</small>`);
                evaluationDetails.hyperItems.push(manualData);
            } else {
                hypoScores[domain.id] = (hypoScores[domain.id] || 0) + mScore;
                hypoCount++;
                addToList(hypoList, `<b>[بند مخصص للأخصائي] ${mText}</b> - <span style="color:#2563eb; font-weight:bold;">[الشدة: ${scoreLabel}]</span> <small style="color:#64748b;">(${domain.name})</small>`);
                evaluationDetails.hypoItems.push(manualData);
            }
        }
    });

    if (hyperCount === 0 && hyperList) {
        hyperList.innerHTML = '<li style="color:#64748b;">لا توجد استجابات فرط أو تجنب حسي مسجلة بدرجة أعلى من الطبيعي.</li>';
    }
    if (hypoCount === 0 && hypoList) {
        hypoList.innerHTML = '<li style="color:#64748b;">لا توجد استجابات نقص أو خمول وبحث حسي مسجلة بدرجة أعلى من الطبيعي.</li>';
    }

    // بناء الخطة العلاجية الشاملة فورياً
    await buildComprehensivePlan(evaluationDetails, affectedDomains);

    // إظهار صندوق التقرير
    const reportBox = document.getElementById('reportBox');
    if (reportBox) reportBox.style.display = 'block';

    // رسم الرسم البياني للشارت
    renderBarChart(hyperScores, hypoScores);

    resetButtonLoading(btnMain);
    if (stickyBtn) resetButtonLoading(stickyBtn);

    // التمرير السلس نحو التقرير
    if (reportBox) {
        reportBox.scrollIntoView({ behavior: 'smooth' });
    }
}

function addToList(listElement, htmlContent) {
    if (!listElement) return;
    const li = document.createElement('li');
    li.innerHTML = htmlContent;
    listElement.appendChild(li);
}

