/**
 * دالة بناء الخطة العلاجية وجدول التوصيات (فورية وموثوقة بنسبة 100%)
 */
async function buildComprehensivePlan(detailsOrDomains, legacyDomains = []) {
    const planBox = document.getElementById('planBox');
    if (!planBox) return;

    let hyperItems = [];
    let hypoItems = [];

    if (detailsOrDomains && typeof detailsOrDomains === 'object' && !Array.isArray(detailsOrDomains)) {
        hyperItems = detailsOrDomains.hyperItems || [];
        hypoItems = detailsOrDomains.hypoItems || [];
    }

    const allItems = [
        ...hyperItems.map(item => ({ ...item, responseType: 'فرط استجابة / تجنب', typeKey: 'hyper' })),
        ...hypoItems.map(item => ({ ...item, responseType: 'نقص استجابة / بحث', typeKey: 'hypo' }))
    ];

    if (allItems.length === 0) {
        planBox.innerHTML = `
            <div style="background:#f0fdf4; border:1px solid #bbf7d0; border-radius:8px; padding:16px; color:#166534; font-size:14px; text-align:right;">
                ✅ <b>المؤشر العام:</b> جميع درجات التقييم الحسي تقع ضمن النطاق الطبيعي المتوازن. يوصى بالحفاظ على الأنشطة التطورية واللعب الحركي الطبيعي ومتابعة التطور الدوري.
            </div>`;
        return;
    }

    // تتبع الأنشطة المستخدمة لضمان عدم تكرار أي نشاط عبر البنود
    let usedActivitiesSet = new Set();
    let rowsHTML = '';
    let counter = 1;

    allItems.forEach(item => {
        const dId = item.domainId || 'v';
        const typeK = item.typeKey || 'hyper';
        const scoreVal = item.score || 1;

        const candidateActivities = (sensoryDietMatrix[dId] && sensoryDietMatrix[dId][typeK]) ? sensoryDietMatrix[dId][typeK] : sensoryDietMatrix['v']['hyper'];

        let selectedActivity = candidateActivities.find(act => !usedActivitiesSet.has(act.name));
        if (!selectedActivity) {
            selectedActivity = candidateActivities[counter % candidateActivities.length];
        } else {
            usedActivitiesSet.add(selectedActivity.name);
        }

        const scoreBadge = scoreVal === 3 ? '<span class="plan-tag hyper">شديد (3/3)</span>' : (scoreVal === 2 ? '<span class="plan-tag" style="background:#fef3c7; color:#b45309; border:1px solid #fde68a;">متوسط (2/3)</span>' : '<span class="plan-tag hypo">بسيط (1/3)</span>');
        const typeBadge = typeK === 'hyper' ? '<span class="plan-tag hyper">🔴 فرط وتجنب</span>' : '<span class="plan-tag hypo">🔵 نقص وبحث</span>';

        rowsHTML += `
            <tr>
                <td style="text-align:center; font-weight:bold; color:#0d3b66;">${counter++}</td>
                <td><b>${item.name}</b></td>
                <td><small style="color:#64748b;">${item.domainName}</small></td>
                <td style="text-align:center;">${scoreBadge}</td>
                <td style="text-align:center;">${typeBadge}</td>
                <td>
                    <div style="font-weight:700; color:#0d3b66; margin-bottom:4px;">🎯 ${selectedActivity.name}</div>
                    <div style="margin-bottom:3px;"><span style="color:#0284c7; font-weight:600;">الهدف:</span> ${selectedActivity.goal}</div>
                    <div style="margin-bottom:3px;"><span style="color:#166534; font-weight:600;">الأدوات والتطبيق:</span> ${selectedActivity.tools}</div>
                    <div style="margin-bottom:3px;"><span style="color:#d97706; font-weight:600;">الجرعة والتكرار:</span> ${selectedActivity.freq}</div>
                    <div><span style="color:#dc2626; font-weight:600;">الأمان:</span> <small>${selectedActivity.safety}</small></div>
                </td>
            </tr>
        `;
    });

    planBox.innerHTML = `
        <div style="background:#f0fdf4; border:1px solid #bbf7d0; border-radius:8px; padding:10px 14px; margin-bottom:12px; color:#166534; font-size:13px; display:flex; align-items:center; gap:8px;">
            <span>✅</span>
            <span><b>تم إعداد الخطة الكلينيكية المخصصة:</b> تم توليد برنامج حمية حسية دقيق لعدد (${allItems.length}) بنداً وفق معايير التكامل الحسي المعتمدة.</span>
        </div>
        <div style="width:100%; overflow-x:auto;">
            <table class="plan-table">
                <thead>
                    <tr>
                        <th style="width:35px; text-align:center;">#</th>
                        <th style="width:22%;">البند الحسي الملاحظ</th>
                        <th style="width:14%;">النظام الحسي</th>
                        <th style="width:10%; text-align:center;">الشدة</th>
                        <th style="width:12%; text-align:center;">النمط</th>
                        <th>البرنامج العلاجي والنشاط الحسي الموصى به</th>
                    </tr>
                </thead>
                <tbody>
                    ${rowsHTML}
                </tbody>
            </table>
        </div>
    `;
}

/**
 * دالة رسم الرسم البياني المزدوج عبر Chart.js للمجالات التسعة
 */
function renderBarChart(hyperScores, hypoScores) {
    const canvasElem = document.getElementById('sensoryChart');
    if (!canvasElem) return;
    const ctx = canvasElem.getContext('2d');

    if (myChart) {
        myChart.destroy();
    }

    myChart = new Chart(ctx, {
        type: 'bar',
        data: {
            labels: [
                'الدهليزي والتوازن',
                'النظام اللمسي',
                'النظام السمعي',
                'النظام البصري',
                'حاسة الشم',
                'حاسة التذوق والفم',
                'الحس الأحشائي',
                'الحس العضلي العميق',
                'السلوكي والنمطي'
            ],
            datasets: [
                {
                    label: '🔴 فرط استجابة / تجنب حسي (Hyper)',
                    data: [
                        hyperScores.v || 0,
                        hyperScores.t || 0,
                        hyperScores.a || 0,
                        hyperScores.vsl || 0,
                        hyperScores.olf || 0,
                        hyperScores.gus || 0,
                        hyperScores.mus || 0,
                        hyperScores.p || 0,
                        hyperScores.c || 0
                    ],
                    backgroundColor: '#dc2626',
                    borderColor: '#b91c1c',
                    borderWidth: 1,
                    borderRadius: 4
                },
                {
                    label: '🔵 نقص استجابة / خمول وبحث (Hypo)',
                    data: [
                        hypoScores.v || 0,
                        hypoScores.t || 0,
                        hypoScores.a || 0,
                        hypoScores.vsl || 0,
                        hypoScores.olf || 0,
                        hypoScores.gus || 0,
                        hypoScores.mus || 0,
                        hypoScores.p || 0,
                        hypoScores.c || 0
                    ],
                    backgroundColor: '#2563eb',
                    borderColor: '#1d4ed8',
                    borderWidth: 1,
                    borderRadius: 4
                }
            ]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            animation: false,
            scales: {
                y: {
                    beginAtZero: true,
                    ticks: { stepSize: 2, font: { size: 10 } },
                    grid: { color: '#f1f5f9' }
                },
                x: {
                    grid: { display: false },
                    ticks: { font: { size: 10.5, family: 'Segoe UI, Tahoma, sans-serif' } }
                }
            },
            plugins: {
                legend: { 
                    position: 'top',
                    labels: {
                        font: { size: 11, family: 'Segoe UI, Tahoma, sans-serif' },
                        boxWidth: 14
                    }
                }
            }
        }
    });
}

/**
 * حفظ ملف وبيانات الطفل في الذاكرة المحلية LocalStorage مع حماية تامة ضد أخطاء null
 */
function saveChildData() {
    const childNameInput = document.getElementById('childName');
    const childName = childNameInput ? childNameInput.value.trim() : '';

    if (!childName) {
        alert('يرجى إدخال اسم الطفل أولاً لإتمام الحفظ.');
        childNameInput?.focus();
        return;
    }

    const formData = {
        name: childName,
        age: document.getElementById('childAge')?.value || '',
        gender: document.getElementById('childGender')?.value || 'ذكر',
        evalDate: document.getElementById('evalDate')?.value || '',
        evaluator: document.getElementById('evaluator')?.value || '',
        scores: {}
    };

    if (typeof domainsData !== 'undefined') {
        domainsData.forEach(domain => {
            domain.items.forEach((_, index) => {
                const num = index + 1;
                const fieldPrefix = `${domain.id}_${num}`;
                const sElem = document.getElementById(`${fieldPrefix}_score`);
                const tElem = document.getElementById(`${fieldPrefix}_type`);

                if (sElem) formData.scores[`${fieldPrefix}_score`] = sElem.value;
                if (tElem) formData.scores[`${fieldPrefix}_type`] = tElem.value;
            });

            const mtElem = document.getElementById(`${domain.id}_manual_text`);
            const msElem = document.getElementById(`${domain.id}_manual_score`);
            const myElem = document.getElementById(`${domain.id}_manual_type`);

            if (mtElem) formData.scores[`${domain.id}_manual_text`] = mtElem.value;
            if (msElem) formData.scores[`${domain.id}_manual_score`] = msElem.value;
            if (myElem) formData.scores[`${domain.id}_manual_type`] = myElem.value;
        });
    }

    let savedChildren = JSON.parse(localStorage.getItem('sensory_children_records') || '{}');
    savedChildren[childName] = formData;
    localStorage.setItem('sensory_children_records', JSON.stringify(savedChildren));

    alert(`✅ تم حفظ تقييم الطفل (${childName}) بنجاح في السجل.`);
    updateSavedChildrenDropdown();
}

/**
 * تحديث قائمة السجلات المحفوظة في القائمة المنسدلة
 */
function updateSavedChildrenDropdown() {
    const select = document.getElementById('savedChildrenSelect');
    if (!select) return;

    select.innerHTML = '<option value="">-- اختر طفلاً من السجل لاسترجاع تقييمه --</option>';
    const savedChildren = JSON.parse(localStorage.getItem('sensory_children_records') || '{}');

    Object.keys(savedChildren).forEach(name => {
        const opt = document.createElement('option');
        opt.value = name;
        opt.textContent = `${name} (${savedChildren[name].evalDate || 'غير مؤرخ'})`;
        select.appendChild(opt);
    });
}

/**
 * تحميل واسترجاع بيانات الطفل المحدد من السجل
 */
function loadSelectedChild() {
    const select = document.getElementById('savedChildrenSelect');
    const selectedName = select ? select.value : '';

    if (!selectedName) {
        alert('يرجى اختيار طفل من القائمة أولاً.');
        return;
    }

    const savedChildren = JSON.parse(localStorage.getItem('sensory_children_records') || '{}');
    const data = savedChildren[selectedName];

    if (data) {
        const nameInput = document.getElementById('childName');
        const ageInput = document.getElementById('childAge');
        const genderInput = document.getElementById('childGender');
        const dateInput = document.getElementById('evalDate');
        const evaluatorInput = document.getElementById('evaluator');

        if (nameInput) nameInput.value = data.name || '';
        if (ageInput) ageInput.value = data.age || '';
        if (genderInput) genderInput.value = data.gender || 'ذكر';
        if (dateInput) dateInput.value = data.evalDate || '';
        if (evaluatorInput) evaluatorInput.value = data.evaluator || '';

        // تحديث الاسم في الشريط اللاصق
        const stickyName = document.getElementById('stickyChildName');
        if (stickyName) stickyName.innerText = data.name || '';

        if (data.scores) {
            Object.keys(data.scores).forEach(key => {
                const elem = document.getElementById(key);
                if (elem) elem.value = data.scores[key];
            });
        }

        // تحديث أزرار الـ Pills المرئية لتعكس الدرجات المسترجعة
        if (typeof refreshPillsUI === 'function') {
            refreshPillsUI();
        }

        updateLiveStats();
        generateFullReport();
        alert(`✅ تم تحميل ملف الطفل (${selectedName}) بنجاح واسترجاع درجاته.`);
    }
}

/**
 * حذف ملف الطفل المحدد من السجل المحلي
 */
function deleteSelectedChild() {
    const select = document.getElementById('savedChildrenSelect');
    const selectedName = select ? select.value : '';

    if (!selectedName) {
        alert('يرجى اختيار طفل من القائمة لحذفه.');
        return;
    }

    if (confirm(`هل أنت متأكد من رغبتك في حذف ملف الطفل (${selectedName}) نهائياً من هذا الجهاز؟`)) {
        let savedChildren = JSON.parse(localStorage.getItem('sensory_children_records') || '{}');
        delete savedChildren[selectedName];
        localStorage.setItem('sensory_children_records', JSON.stringify(savedChildren));

        updateSavedChildrenDropdown();
        alert(`🗑️ تم حذف ملف الطفل (${selectedName}) بنجاح.`);
    }
}

/**
 * طباعة التقرير / الحفظ كـ PDF عبر نافذة الطباعة المباشرة والآمنة للمتصفح
 */
function exportToPDF() {
    const reportBox = document.getElementById('reportBox');
    if (!reportBox || reportBox.style.display === 'none') {
        alert("يرجى استخراج التقرير أولاً قبل الطباعة.");
        return;
    }

    window.print();
}

/**
 * تصدير التقرير الكلينيكي إلى ملف Word (.doc) احترافي ومنسق
 */
function exportToWord() {
    const childName = document.getElementById('childName')?.value.trim() || 'طفل';
    const fileName = `تقرير_التكامل_الحسي_${childName}.doc`;

    const reportElement = document.getElementById('reportContent');
    if (!reportElement) {
        alert("عنصر التقرير غير موجود!");
        return;
    }

    let canvasImageHTML = '';
    const originalCanvas = document.querySelector('#reportContent canvas');
    if (originalCanvas) {
        try {
            const chartDataURL = originalCanvas.toDataURL('image/png');
            canvasImageHTML = `<div style="text-align: center; margin: 15px 0;">
                <div style="font-weight: bold; color: #0d3b66; margin-bottom: 6px;">التمثيل البياني للملف الحسي</div>
                <img src="${chartDataURL}" width="520" style="width: 520px; max-width: 100%; height: auto; border: 1px solid #cbd5e1; padding: 6px; border-radius: 6px;" />
            </div>`;
        } catch (e) {
            console.error("تعذر تحويل الرسم البياني لصورة Word:", e);
        }
    }

    let contentHTML = reportElement.innerHTML;
    if (canvasImageHTML) {
        contentHTML = contentHTML.replace(/<canvas[^>]*>[\s\S]*?<\/canvas>/gi, canvasImageHTML);
    }

    const tempDiv = document.createElement('div');
    tempDiv.innerHTML = contentHTML;
    tempDiv.querySelectorAll('img').forEach(img => {
        img.setAttribute('width', '110');
        img.style.width = '110px';
    });
    contentHTML = tempDiv.innerHTML;

    const wordDocHTML = `
    <html xmlns:o='urn:schemas-microsoft-com:office:office'
          xmlns:w='urn:schemas-microsoft-com:office:word'
          xmlns='http://www.w3.org/TR/REC-html40' dir='rtl'>
    <head>
        <meta charset='utf-8'>
        <title>تقرير التكامل الحسي - ${childName}</title>
        <!--[if gte mso 9]>
        <xml>
            <w:WordDocument>
                <w:View>Print</w:View>
                <w:Zoom>100</w:Zoom>
                <w:DoNotOptimizeForBrowser/>
            </w:WordDocument>
        </xml>
        <![endif]-->
        <style>
            @page Section1 {
                size: 210mm 297mm;
                margin: 18mm 14mm 18mm 14mm;
            }
            div.Section1 { page: Section1; }
            body {
                font-family: 'Segoe UI', Arial, 'Traditional Arabic', sans-serif;
                direction: rtl;
                text-align: right;
                color: #1e293b;
                line-height: 1.6;
                font-size: 11pt;
            }
            h2 { color: #0d3b66; font-size: 15pt; margin-bottom: 4px; }
            h3 { color: #0284c7; font-size: 12pt; margin: 12px 0 6px 0; }
            table { width: 100%; border-collapse: collapse; margin-bottom: 14px; }
            th { background-color: #0d3b66; color: #ffffff; padding: 8px; border: 1px solid #1e4976; font-size: 10pt; }
            td { border: 1px solid #cbd5e1; padding: 7px 9px; font-size: 9.5pt; vertical-align: top; }
            tr:nth-child(even) td { background-color: #f8fafc; }
            .info-table td { background-color: #f8fafc; }
            .hypo-list { background-color: #eff6ff; border-right: 4px solid #2563eb; padding: 10px; margin-bottom: 12px; }
            .hyper-list { background-color: #fef2f2; border-right: 4px solid #dc2626; padding: 10px; margin-bottom: 12px; }
            ul { margin-right: 18px; padding-right: 0; }
            li { margin-bottom: 4px; }
        </style>
    </head>
    <body>
        <div class="Section1">
            ${contentHTML}
        </div>
    </body>
    </html>
    `;

    const blob = new Blob(['\ufeff' + wordDocHTML], { type: 'application/msword;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = fileName;
    document.body.appendChild(link);
    link.click();

    setTimeout(() => {
        document.body.removeChild(link);
        URL.revokeObjectURL(url);
    }, 100);
}

function setButtonLoading(btn, text) {
    if (!btn) return;
    btn.dataset.originalText = btn.innerHTML;
    btn.classList.add('btn-loading');
    btn.disabled = true;
}

function resetButtonLoading(btn) {
    if (!btn) return;
    btn.classList.remove('btn-loading');
    btn.disabled = false;
    if (btn.dataset.originalText) {
        btn.innerHTML = btn.dataset.originalText;
    }
}
